export function shouldForwardReasoningEffort(model, {
  env = process.env,
  baseUrl = process.env.OPENAI_BASE_URL || 'https://api.openai.com/v1',
} = {}) {
  const mode = String(env.ANYMODEL_FORWARD_EFFORT || '').toLowerCase();
  if (['1', 'true', 'on', 'yes'].includes(mode)) return true;
  if (['0', 'false', 'off', 'no'].includes(mode)) return false;

  // Default: only forward effort for native OpenAI endpoints (gateway compatibility)
  // Native reasoning models retain modern token-budget field; generic custom models retain max_tokens.
  try {
    const host = new URL(baseUrl).hostname;
    if (!/(^|\.)api\.openai\.com$/i.test(host)) return false;
  } catch {
    return false;
  }

  const m = String(model || '').toLowerCase();
  // Native reasoning models: GPT-5/GPT-6 and o-series (o1, o2, etc.)
  // These support reasoning_effort and max_completion_tokens budget field.
  return /(^|[/_-])(gpt-5|gpt-6|o[1-9])/.test(m) || m.includes('codex');
}

