    // undefined` and over-generate.
    // For native reasoning models (GPT-5/GPT-6, o-series), use max_completion_tokens as the budget field.
    // For legacy/custom servers, retain max_tokens (max_tokens is a client-side fallback budget).
    max_tokens: anthropicBody.max_tokens ?? anthropicBody.max_output_tokens,
    stream: anthropicBody.stream || false,
    messages: [],
  };

